package net.zartra.gui;
import org.bukkit.command.PluginCommand;import org.bukkit.entity.Player;import org.bukkit.plugin.java.JavaPlugin;import java.io.File;
public final class ZartraGUIPlugin extends JavaPlugin {private MenuManager menus;private GuiService gui;private ChatInputManager inputs;private ZGuiCommand command;private ActionExecutor actions;private VariableStore variables;private VariableStorage variableStorage;
 public void onEnable(){try{getLogger().info("Enabling on "+getServer().getName()+" "+getServer().getVersion()+" (Java "+System.getProperty("java.version")+")");saveDefaultConfig();saveResource("messages.yml",false);variables=new VariableStore();variableStorage=new VariableStorage(new File(getDataFolder(),"variables.yml"));variableStorage.load(variables);inputs=new ChatInputManager(getConfig().getLong("chat-input-timeout-seconds",60));menus=new MenuManager(new MenuStorage(new File(getDataFolder(),"menus"),getLogger()));gui=new GuiService(this,menus);actions=new ActionExecutor(this,menus);menus.runtime(this,actions);getServer().getMessenger().registerOutgoingPluginChannel(this,"BungeeCord");command=new ZGuiCommand(this,menus,gui);PluginCommand root=getCommand("zgui");if(root==null)throw new IllegalStateException("plugin.yml does not declare zgui");root.setExecutor(command);root.setTabCompleter(command);getServer().getPluginManager().registerEvents(new GuiListener(this,menus,gui),this);getLogger().info("Enabled: "+menus.all().size()+" menu(s) loaded; legacy API compatible.");}catch(Exception e){getLogger().severe("Failed to enable ZartraGUI: "+e.getMessage());e.printStackTrace();getServer().getPluginManager().disablePlugin(this);}}
 void askCreate(final Player p){inputs.begin(p,new ChatInputManager.Callback(){public void run(Player who,String text){command.create(who,text);}});p.sendMessage(Chat.c("&eEnter a lowercase menu ID."));} ChatInputManager inputs(){return inputs;} ActionExecutor actions(){return actions;} VariableStore variables(){return variables;} public void onDisable(){if(menus!=null)menus.shutdown();if(inputs!=null)inputs.clear();try{if(variableStorage!=null)variableStorage.save(variables);}catch(Exception e){getLogger().warning("Variable save failed: "+e.getMessage());}try{if(menus!=null)for(MenuDefinition d:menus.all())menus.save(d);}catch(Exception e){getLogger().warning("Save during shutdown failed: "+e.getMessage());}}
}
